#!/bin/bash
#
# package() installs every file the device tree requests in the folders the package provides, each
# from the file in the OEM download it was matched to, and checks each one's SHA-256.
#
# Generated by bin/snapdragon-firmware-recipes with the PKGBUILD next to it; change the table or
# the generator, not this file.

set -euo pipefail

package_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
scratch=$(mktemp -d)
trap 'rm -rf "$scratch"' EXIT

fail() {
  echo "not ok - $1" >&2
  exit 1
}

source "$package_dir/PKGBUILD"
[[ " ${arch[*]} " == " aarch64 " ]] || fail "the package is aarch64-only"
[[ -z ${groups[*]:-} ]] || fail "the package is in no group, so only the machine it is for installs it"
[[ ${provides[*]} == 'qcom-firmware-x1e80100-dell-inspiron-14-plus-7441' ]] || fail "the package provides the firmware folders it fills"

# Each installed file, then the file in the unpacked OEM download it comes from.
files=(
  'qcom/x1e80100/dell/inspiron-14-plus-7441/adsp_dtbs.elf' 'dell-10wkv/16299/Drivers/arm64/qcsubsys_ext_adsp8380/adsp_dtbs.elf'
  'qcom/x1e80100/dell/inspiron-14-plus-7441/adspr.jsn' 'dell-10wkv/16299/Drivers/arm64/qcsubsys_ext_adsp8380/adspr.jsn'
  'qcom/x1e80100/dell/inspiron-14-plus-7441/adsps.jsn' 'dell-10wkv/16299/Drivers/arm64/qcsubsys_ext_adsp8380/adsps.jsn'
  'qcom/x1e80100/dell/inspiron-14-plus-7441/adspua.jsn' 'dell-10wkv/16299/Drivers/arm64/qcsubsys_ext_adsp8380/adspua.jsn'
  'qcom/x1e80100/dell/inspiron-14-plus-7441/battmgr.jsn' 'dell-10wkv/16299/Drivers/arm64/qcsubsys_ext_adsp8380/battmgr.jsn'
  'qcom/x1e80100/dell/inspiron-14-plus-7441/cdsp_dtbs.elf' 'dell-10wkv/16299/Drivers/arm64/qcnspmcdm_ext_cdsp8380/cdsp_dtbs.elf'
  'qcom/x1e80100/dell/inspiron-14-plus-7441/cdspr.jsn' 'dell-10wkv/16299/Drivers/arm64/qcnspmcdm_ext_cdsp8380/cdspr.jsn'
  'qcom/x1e80100/dell/inspiron-14-plus-7441/qcadsp8380.mbn' 'dell-10wkv/16299/Drivers/arm64/qcsubsys_ext_adsp8380/qcadsp8380.mbn'
  'qcom/x1e80100/dell/inspiron-14-plus-7441/qccdsp8380.mbn' 'dell-10wkv/16299/Drivers/arm64/qcnspmcdm_ext_cdsp8380/qccdsp8380.mbn'
  'qcom/x1e80100/dell/inspiron-14-plus-7441/qcdxkmsuc8380.mbn' 'dell-2chk7/16299/Drivers/MUP/qcdx8380/qcdxkmsuc8380.mbn'
  'qcom/x1e80100/dell/inspiron-14-plus-7441/qcvss8380.mbn' 'dell-2chk7/16299/Drivers/MUP/qcdx8380/qcvss8380.mbn'
)

# Stand in for the unpacked downloads, each file holding its own path.
srcdir="$scratch/src"
for ((i = 0; i < ${#files[@]}; i += 2)); do
  mkdir -p "$srcdir/$(dirname -- "${files[i + 1]}")"
  printf '%s\n' "${files[i + 1]}" >"$srcdir/${files[i + 1]}"
done

# The stand-ins cannot match the real SHA-256s, so record the list package() checks instead.
sha256sum() { cat >"$scratch/checked"; }

pkgdir="$scratch/pkg"
(cd "$srcdir" && package)

fw="$pkgdir/usr/lib/firmware"
for ((i = 0; i < ${#files[@]}; i += 2)); do
  [[ -f $fw/${files[i]} && $(<"$fw/${files[i]}") == "${files[i + 1]}" ]] ||
    fail "installs ${files[i + 1]} as ${files[i]}"
done
installed=$(cd "$fw" && find . -type f | sed 's|^\./||' | LC_ALL=C sort)
[[ $(wc -l <<<"$installed") -eq $((${#files[@]} / 2)) ]] || fail "installs only the files the device tree requests"
[[ $(awk '{print $2}' "$scratch/checked" | LC_ALL=C sort) == "$installed" ]] ||
  fail "checks every installed file against its SHA-256"
for folder in 'qcom/x1e80100/dell/inspiron-14-plus-7441'; do
  [[ -n $(find "$fw/$folder" -maxdepth 1 -type f) ]] || fail "fills $folder, which it provides"
done

echo "ok - dell-inspiron-14-plus-7441-firmware"
